#!/bin/sh

# Syncs the skills-service-manager's code to a robot. It's copied to where it will be when it gets
# into buildroot

# Get the default robot's hostname
robotHost=`./bin/utils/get-robot-host.sh`;

echo "\nSyncing jibo-ssm changes to $robotHost...\n"

# Run SyncIgnore to generate a list of files
node ./node_modules/jibo-syncignore/bin/syncignore.js --debug

# Colorize the output
echo "\x1b[90m";

# Copy over stuff to /user/local/bin/jibo-ssm
rsync -av -L -p --delete --force \
    --exclude-from=$(pwd)/.syncignore \
    --exclude-from=$(pwd)/.syncignore-auto \
    . \
    root@$robotHost:/usr/local/bin/jibo-ssm/

# Copy necessary configs to /usr/local/etc/jibo-ssm
rsync -av -p --delete --force \
    --include '*/' --include 'jibo-ssm*.json' --exclude '*' \
    ./configs/ \
    root@$robotHost:/usr/local/etc/jibo-ssm/


# Fix root ownership under /usr/local
ssh root@$robotHost 'chown -R root:root /usr/local/bin/jibo-ssm'
# ssh root@$robotHost 'chown -R root:root /usr/local/etc/jibo-ssm'

echo "\n\x1b[92;1mDone.";

# Reset color
echo "\x1b[39;49;00m";
